void UCharacterMovementComponent::StartFalling(int32 Iterations, float remainingTime, float timeTick, const FVector& Delta, const FVector& subLoc)
{
	// start falling 
	const float DesiredDist = Delta.Size();
	const float ActualDist = ProjectToGravityFloor(UpdatedComponent->GetComponentLocation() - subLoc).Size();
	remainingTime = (DesiredDist < UE_KINDA_SMALL_NUMBER)
					? 0.f
					: remainingTime + timeTick * (1.f - FMath::Min(1.f,ActualDist/DesiredDist));

	if ( IsMovingOnGround() )
	{
		// This is to catch cases where the first frame of PIE is executed, and the
		// level is not yet visible. In those cases, the player will fall out of the
		// world... So, don't set MOVE_Falling straight away.
		if ( !GIsEditor || (GetWorld()->HasBegunPlay() && (GetWorld()->GetTimeSeconds() >= 1.f)) )
		{
			SetMovementMode(MOVE_Falling); //default behavior if script didn't change physics
		}
		else
		{
			// Make sure that the floor check code continues processing during this delay.
			bForceNextFloorCheck = true;
		}
	}
	StartNewPhysics(remainingTime,Iterations);
}


void UCharacterMovementComponent::RevertMove(const FVector& OldLocation, FMovementBaseInterfaceData* OldMovementBaseInterfaceData, const FVector& PreviousBaseLocation, const FFindFloorResult& OldFloor, bool bFailMove)
{
	//UE_LOGF(LogCharacterMovement, Log, "RevertMove from %f %f %f to %f %f %f", CharacterOwner->Location.X, CharacterOwner->Location.Y, CharacterOwner->Location.Z, OldLocation.X, OldLocation.Y, OldLocation.Z);

else
{
	FindFloor(UpdatedComponent->GetComponentLocation(), CurrentFloor, bZeroDelta, NULL);
}

// check for ledges here
const bool bCheckLedges = !CanWalkOffLedges();
if ( bCheckLedges && !CurrentFloor.IsWalkableFloor() )
{
	// calculate possible alternate movement
	const FVector NewDelta = bTriedLedgeMove ? FVector::ZeroVector : GetLedgeMove(OldLocation, Delta, OldFloor);
	if ( !NewDelta.IsZero() )
	{
		// first revert this move
		RevertMove(OldLocation, OldMovementBaseInterfaceData, PreviousBaseLocation, OldFloor, false);

		// avoid repeated ledge moves if the first one fails
		bTriedLedgeMove = true;

		// Try new movement direction
		Velocity = NewDelta/timeTick;
		remainingTime += timeTick;
		Iterations--;
		continue;
	}
	else
	{
		// see if it is OK to jump
		// @todo collision : only thing that can be problem is that oldbase has world collision on
		const bool bOldMovementBaseValid = OldMovementBaseInterfaceData && OldMovementBaseInterfaceData->IsValid();
		bool bMustJump = bZeroDelta || (!bOldMovementBaseValid || (!CollisionEnabledHasQuery(OldMovementBaseInterfaceData->GetBodyInstanceOwner()->GetCollisionEnabled()) && MovementBaseUtility::IsDynamicBase(OldMovementBaseInterfaceData)));
		if ( (bMustJump || !bCheckedFall) && CheckFall(OldFloor, CurrentFloor.HitResult, Delta, OldLocation, remainingTime, timeTick, Iterations, bMustJump) )
		{
			return;
		}
		bCheckedFall = true;

		// revert this move
		RevertMove(OldLocation, OldMovementBaseInterfaceData, PreviousBaseLocation, OldFloor, true);
		remainingTime = 0.f;
		break;
	}
}
else
{
	// Validate the floor check
	if (CurrentFloor.IsWalkableFloor())
	{
		if (ShouldCatchAir(OldFloor, CurrentFloor))
		{
			HandleWalkingOffLedge(OldFloor.HitResult.ImpactNormal, OldFloor.HitResult.Normal, OldLocation, timeTick);
			if (IsMovingOnGround())
			{
				// If still walking, then fall. If not, assume the user set a different mode they want to keep.
				StartFalling(Iterations, remainingTime, timeTick, Delta, OldLocation);
			}
			return;
		}

		AdjustFloorHeight();
		SetBaseFromFloor(CurrentFloor);
	}
	else if (CurrentFloor.HitResult.bStartPenetrating && remainingTime <= 0.f)
	{
		// The floor check failed because it started in penetration
		// We do not want to try to move downward because the downward sweep failed, rather we'd like to try to pop out of the floor.
		FHitResult Hit(CurrentFloor.HitResult);
		Hit.TraceEnd = Hit.TraceStart + MAX_FLOOR_DIST * -GetGravityDirection();
		const FVector RequestedAdjustment = GetPenetrationAdjustment(Hit);
		ResolvePenetration(RequestedAdjustment, Hit, UpdatedComponent->GetComponentQuat());
		bForceNextFloorCheck = true;
	}

	// check if just entered water
	if ( IsSwimming() )
	{
		StartSwimming(OldLocation, Velocity, timeTick, remainingTime, Iterations);
		return;
	}

	// See if we need to start falling.
	if (!CurrentFloor.IsWalkableFloor() && !CurrentFloor.HitResult.bStartPenetrating)
	{
		const bool bOldMovementBaseValid = OldMovementBaseInterfaceData && OldMovementBaseInterfaceData->IsValid();
		const bool bMustJump = bJustTeleported || bZeroDelta || (!bOldMovementBaseValid || (!CollisionEnabledHasQuery(OldMovementBaseInterfaceData->GetBodyInstanceOwner()->GetCollisionEnabled()) && MovementBaseUtility::IsDynamicBase(OldMovementBaseInterfaceData)));
		if ((bMustJump || !bCheckedFall) && CheckFall(OldFloor, CurrentFloor.HitResult, Delta, OldLocation, remainingTime, timeTick, Iterations, bMustJump) )
		{
			return;
		}
		bCheckedFall = true;

	// OutFloorResult.HitResult is now the result of the vertical floor check.
	// See if we should try to "perch" at this location.
	if (bNeedToValidateFloor && OutFloorResult.bBlockingHit && !OutFloorResult.bLineTrace)
	{
		const bool bCheckRadius = true;
		if (ShouldComputePerchResult(OutFloorResult.HitResult, bCheckRadius))
		{
			float MaxPerchFloorDist = FMath::Max(MAX_FLOOR_DIST, MaxStepHeight + HeightCheckAdjust);
			if (IsMovingOnGround())
			{
				MaxPerchFloorDist += FMath::Max(0.f, PerchAdditionalHeight);
			}

			FFindFloorResult PerchFloorResult;
			if (ComputePerchResult(GetValidPerchRadius(), OutFloorResult.HitResult, MaxPerchFloorDist, PerchFloorResult))
			{
				// Don't allow the floor distance adjustment to push us up too high, or we will move beyond the perch distance and fall next time.
				const float AvgFloorDist = (MIN_FLOOR_DIST + MAX_FLOOR_DIST) * 0.5f;
				const float MoveUpDist = (AvgFloorDist - OutFloorResult.FloorDist);
				if (MoveUpDist + PerchFloorResult.FloorDist >= MaxPerchFloorDist)
				{
					OutFloorResult.FloorDist = AvgFloorDist;
				}

				// If the regular capsule is on an unwalkable surface but the perched one would allow us to stand, override the normal to be one that is walkable.
				if (!OutFloorResult.bWalkableFloor)
				{
					// Floor distances are used as the distance of the regular capsule to the point of collision, to make sure AdjustFloorHeight() behaves correctly.
					OutFloorResult.SetFromLineTrace(PerchFloorResult.HitResult, OutFloorResult.FloorDist, FMath::Max(OutFloorResult.FloorDist, MIN_FLOOR_DIST), true);
				}
			}
			else
			{
				// We had no floor (or an invalid one because it was unwalkable), and couldn't perch here, so invalidate floor (which will cause us to start falling).
				OutFloorResult.bWalkableFloor = false;
			}
		}
	}
}

fn adjust_walking_floor_height(
    spatial: &SpatialQuery, capsule: &Collider, transform: &mut Transform, half: f32, radius: f32,
    cmc: &crate::als::params::CmcAdapterParams, entity: Entity,
    candidates: &Query<(Option<&CollisionLayers>, Has<Sensor>, Option<&ColliderOf>, Option<&AlsCollisionLayerOwnership>)>,
) -> bool {
    let filter = SpatialQueryFilter::from_excluded_entities([entity]);
    let Some((center, _, _)) = find_ground_floor(spatial, transform.translation, half, radius, cmc,
        LocomotionState::Grounded, &filter, entity, candidates) else { return false };
    if !(MIN_FLOOR_DISTANCE..=MAX_FLOOR_DISTANCE).contains(&(transform.translation.y - center)) {
        let adjustment = Vec3::Y * (center + (MIN_FLOOR_DISTANCE + MAX_FLOOR_DISTANCE) * 0.5 - transform.translation.y);
        if let Ok((direction, distance)) = Dir3::new_and_length(adjustment) {
            let hit = spatial.cast_shape_predicate(capsule, transform.translation, transform.rotation,
                direction, &ShapeCastConfig { ignore_origin_penetration: true,
                    ..ShapeCastConfig::from_max_distance(distance) }, &filter,
                &|candidate| character_blocks_collider(entity, candidate, candidates));
            transform.translation += *direction * hit.map_or(distance, |hit| movement_sweep_travel(distance, hit.distance));
        }
    }
    true
}

fn walking_movement_transaction(
    spatial: &SpatialQuery, capsule: &Collider, mut transform: Transform, half: f32, radius: f32,
    velocity: Vec3, desired_motion: Vec3, max_speed: f32, dynamics: crate::als::params::GroundedDynamics,
    cmc: &crate::als::params::CmcAdapterParams, friction: f32, delta: f32, entity: Entity,
    candidates: &Query<(Option<&CollisionLayers>, Has<Sensor>, Option<&ColliderOf>, Option<&AlsCollisionLayerOwnership>)>,
    step_permissions: &Query<&AlsMantleTargetPermission>,
) -> (Transform, Vec3, u32, f32, bool, Vec3) {
    let mut last_input = velocity;
    let mut lost_floor = false;
    let (velocity, steps, _, remaining_time) = crate::als::dynamics::simulate_grounded_motion_until_mode_change(
        velocity, desired_motion, max_speed, dynamics, cmc, friction, delta, |step_velocity, step_seconds| {
            last_input = step_velocity;
            let center = transform.translation;
            let requested = step_velocity * step_seconds;
            let Some((advanced, remaining, next_y)) = grounded_movement_transaction(spatial, capsule, center,
                transform.rotation, half, radius, requested, cmc, LocomotionState::Grounded, entity, candidates, step_permissions)
                else { return (step_velocity, Vec3::ZERO, true) };
            transform.translation = advanced + remaining.unwrap_or(requested);
            if let Some(next_y) = next_y && next_y > center.y { transform.translation.y = next_y; }
            lost_floor = !adjust_walking_floor_height(spatial, capsule, &mut transform, half, radius, cmc, entity, candidates);
            let applied = transform.translation - center;
            (applied.with_y(0.0) / step_seconds, applied, !lost_floor)
        });
    (transform, velocity, steps, remaining_time, lost_floor, last_input)

let max_speed = crate::als::dynamics::max_allowed_speed(params, *stance, *rotation_mode,
    max_allowed_gait.0, base.relative_velocity, view_yaw.0);
let factor = braking.map_or(crate::als::dynamics::BRAKING_FRICTION_FACTOR, |state| state.factor);
let support = base.support_velocity.with_y(0.0);
let (moved, mut final_velocity, iterations, remaining_time, lost_floor, last_input) = walking_movement_transaction(
    &spatial_query, capsule, current_transform, half, radius, base.relative_velocity,
    controller.basis.desired_motion, max_speed, dynamics.0, &params.cmc, factor, delta_seconds, entity, &candidates, &step_permissions);
current_transform = moved;
if lost_floor {
    *loco = LocomotionState::Air;
    transitions.write(StateTransitionEvent { entity, dimension: Dimension::LocomotionState,
        from: StateValue::LocomotionState(LocomotionState::Grounded),
        to: StateValue::LocomotionState(LocomotionState::Air) });
    final_velocity += support;
    let terminal = physics_modes.get(entity).ok().and_then(|(_, volume, _)| volume)
        .unwrap_or(&default_volume.0).terminal_velocity;
    let (moved, falling_velocity, _, contact, mode) = falling_movement_transaction(&spatial_query,
        capsule, current_transform, final_velocity, controller.basis.desired_motion, max_speed,
        params, gravity.value, grounded, landing, terminal, remaining_time, iterations, entity, &candidates, &step_permissions, &mut transitions);
    if *loco != mode { *loco = mode; }
    if mode == LocomotionState::None {
        commands.entity(entity).insert((crate::als::state::AlsNotifyLocomotionAction::Ragdolling,
            crate::als::dynamics::AlsMovementBase::default(), LinearVelocity::ZERO));
        *base = default();
    }
    current_transform = moved;
    final_velocity = falling_velocity;
    runtime.airborne_sweep_contact |= contact;
}
runtime.grounded_movement_delta = None;
runtime.grounded_collision_velocity = Some(if *loco == LocomotionState::None { Vec3::ZERO }
    else if lost_floor { final_velocity } else { final_velocity + support });
runtime.grounded_move_start = None;
base.pre_collision_velocity = Some(last_input);
let world_position = current_transform.translation;
*transform = current_transform;

    (if remaining > cmc.max_simulation_time_step && iteration < cmc.max_simulation_iterations {
        cmc.max_simulation_time_step.min(remaining * 0.5)
    } else { remaining }).max(MIN_MOVEMENT_DELTA_SECONDS)
}

pub(crate) fn simulate_grounded_motion_until_mode_change(
    velocity: Vec3, desired_motion: Vec3, max_speed: f32, dynamics: GroundedDynamics,
    cmc: &CmcAdapterParams, braking_friction_factor: f32, delta_seconds: f32,
    mut movement: impl FnMut(Vec3, f32) -> (Vec3, Vec3, bool),
) -> (Vec3, u32, Vec3, f32) {
    let mut remaining = delta_seconds.max(0.0);
    let max_iterations = cmc.max_simulation_iterations;
    let mut current = velocity;
    let mut substeps = 0;
    let mut displacement = Vec3::ZERO;
    while remaining >= MIN_MOVEMENT_DELTA_SECONDS && substeps < max_iterations {
        let step = source_movement_time_step(remaining, cmc, substeps + 1);
        current = grounded_velocity_step_with_braking_friction(
            current,
            desired_motion,
            max_speed,
            dynamics,
            cmc.min_analog_walk_speed,
            braking_friction_factor,
            cmc.braking_substep_time,
            step,
        );
        let (actual_velocity, applied, continue_walking) = movement(current, step);
        remaining -= step;
        substeps += 1;
        displacement += applied;
        if !continue_walking {
            let desired_distance = current.length() * step;
            remaining = if desired_distance < crate::als::movement_constants::SMALL_MOVEMENT_DISTANCE {
                0.0
            } else {
                remaining + step * (1.0 - (applied.with_y(0.0).length() / desired_distance).min(1.0))
            };
            break;
        }
        current = actual_velocity;
    }
    (current, substeps, displacement, remaining)
}

